-- Course foundation. Safe to rerun; no existing records are deleted or published.
-- Apply together with v7 stable-identity migration before using authoring endpoints.
 CREATE TABLE IF NOT EXISTS course_catalog (
 id BIGINT NOT NULL PRIMARY KEY, courseCode VARCHAR(128) NOT NULL UNIQUE,
 title VARCHAR(200) NOT NULL, description TEXT, status VARCHAR(24) NOT NULL DEFAULT 'DRAFT',
 createTime DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updateTime DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, isDelete TINYINT NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS course_section (
 id BIGINT NOT NULL PRIMARY KEY, sectionCode VARCHAR(128) NOT NULL UNIQUE, courseCode VARCHAR(128) NOT NULL,
 parentSectionCode VARCHAR(128), title VARCHAR(200) NOT NULL, textbookNumber VARCHAR(32), sectionType VARCHAR(16) NOT NULL,
 sortOrder INT NOT NULL DEFAULT 0, sourceCode VARCHAR(128), pageStart INT, metadataJson JSON,
 createTime DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updateTime DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, isDelete TINYINT NOT NULL DEFAULT 0,
 KEY idx_course_parent(courseCode,parentSectionCode,sortOrder)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS course_source (
 id BIGINT NOT NULL PRIMARY KEY, sourceCode VARCHAR(128) NOT NULL UNIQUE, metadataJson JSON NOT NULL,
 createTime DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updateTime DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, isDelete TINYINT NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS learning_content_chunk (
 id BIGINT NOT NULL PRIMARY KEY, chunkCode VARCHAR(128) NOT NULL UNIQUE, courseCode VARCHAR(128) NOT NULL, sectionCode VARCHAR(128) NOT NULL,
 title VARCHAR(200) NOT NULL, chunkType VARCHAR(32) NOT NULL, contentMd LONGTEXT NOT NULL,
 revision INT NOT NULL DEFAULT 1, reviewStatus VARCHAR(16) NOT NULL DEFAULT 'DRAFT', draftJson JSON NOT NULL, publishedJson JSON,
 userId BIGINT NOT NULL, contributor VARCHAR(64),
 createTime DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updateTime DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, isDelete TINYINT NOT NULL DEFAULT 0,
 KEY idx_chunk_section(sectionCode), KEY idx_chunk_status(reviewStatus)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS learning_content_chunk_node (
 id BIGINT NOT NULL PRIMARY KEY, chunkCode VARCHAR(128) NOT NULL, nodeCode VARCHAR(128) NOT NULL,
 createTime DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uk_chunk_node(chunkCode,nodeCode), KEY idx_chunk_node(nodeCode)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS learning_unit (
 id BIGINT NOT NULL PRIMARY KEY, unitCode VARCHAR(128) NOT NULL UNIQUE, courseCode VARCHAR(128) NOT NULL, sectionCode VARCHAR(128) NOT NULL,
 title VARCHAR(200) NOT NULL, sortOrder INT NOT NULL DEFAULT 0, estimatedMinutes INT NOT NULL DEFAULT 0,
 revision INT NOT NULL DEFAULT 1, reviewStatus VARCHAR(16) NOT NULL DEFAULT 'DRAFT', draftJson JSON NOT NULL, publishedJson JSON,
 userId BIGINT NOT NULL, contributor VARCHAR(64),
 createTime DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updateTime DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, isDelete TINYINT NOT NULL DEFAULT 0,
 KEY idx_unit_course(courseCode,sortOrder), KEY idx_unit_section(sectionCode)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS learning_unit_activity (
 id BIGINT NOT NULL PRIMARY KEY, activityCode VARCHAR(128) NOT NULL UNIQUE, unitCode VARCHAR(128) NOT NULL,
 activityType VARCHAR(24) NOT NULL, sortOrder INT NOT NULL, required TINYINT NOT NULL DEFAULT 1,
 referenceKind VARCHAR(24) NOT NULL, referenceCode VARCHAR(128) NOT NULL, completionRule VARCHAR(24) NOT NULL, configJson JSON,
 createTime DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updateTime DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, isDelete TINYINT NOT NULL DEFAULT 0,
 KEY idx_activity_unit(unitCode,sortOrder)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS learning_unit_node (
 id BIGINT NOT NULL PRIMARY KEY, unitCode VARCHAR(128) NOT NULL, nodeCode VARCHAR(128) NOT NULL, role VARCHAR(24) NOT NULL,
 createTime DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uk_unit_node(unitCode,nodeCode,role), KEY idx_unit_node(nodeCode)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS learning_activity_progress (
 id BIGINT NOT NULL PRIMARY KEY, userId BIGINT NOT NULL, unitCode VARCHAR(128) NOT NULL, activityCode VARCHAR(128) NOT NULL,
 completed TINYINT NOT NULL DEFAULT 0, passed TINYINT, evidenceType VARCHAR(32), evidenceId VARCHAR(128),
 createTime DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updateTime DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, isDelete TINYINT NOT NULL DEFAULT 0,
 UNIQUE KEY uk_user_activity(userId,activityCode), KEY idx_progress_unit(userId,unitCode)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS learning_course_position (
 id BIGINT NOT NULL PRIMARY KEY, userId BIGINT NOT NULL, courseCode VARCHAR(128) NOT NULL, unitCode VARCHAR(128), activityCode VARCHAR(128),
 createTime DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updateTime DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, isDelete TINYINT NOT NULL DEFAULT 0,
 UNIQUE KEY uk_user_course(userId,courseCode)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS learning_unit_position (
 id BIGINT NOT NULL PRIMARY KEY, userId BIGINT NOT NULL, unitCode VARCHAR(128) NOT NULL, activityCode VARCHAR(128) NOT NULL,
 mode VARCHAR(16) NOT NULL DEFAULT 'MAINLINE', createTime DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 updateTime DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 UNIQUE KEY uk_user_unit_position(userId,unitCode)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS course_resource (
 id BIGINT NOT NULL PRIMARY KEY, resourceCode VARCHAR(128) NOT NULL UNIQUE, resourceType VARCHAR(24) NOT NULL,
 title VARCHAR(200) NOT NULL, questionId BIGINT, adapterKey VARCHAR(128), algorithmKey VARCHAR(128), status VARCHAR(24) NOT NULL DEFAULT 'DRAFT', metadataJson JSON,
 createTime DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updateTime DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, isDelete TINYINT NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS course_content_revision (
 id BIGINT NOT NULL PRIMARY KEY, entityType VARCHAR(24) NOT NULL, entityCode VARCHAR(128) NOT NULL, revision INT NOT NULL,
 snapshotJson JSON NOT NULL, authorId BIGINT NOT NULL, createTime DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 UNIQUE KEY uk_content_revision(entityType,entityCode,revision)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS course_content_review (
 id BIGINT NOT NULL PRIMARY KEY, entityType VARCHAR(24) NOT NULL, entityCode VARCHAR(128) NOT NULL, revision INT NOT NULL,
 action VARCHAR(24) NOT NULL, reviewerId BIGINT NOT NULL, reason VARCHAR(1000), createTime DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 KEY idx_content_review(entityType,entityCode,revision)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS course_import_run (
 id BIGINT NOT NULL PRIMARY KEY, importRunCode VARCHAR(128) NOT NULL UNIQUE, batchCode VARCHAR(128) NOT NULL,
 packageType VARCHAR(24) NOT NULL, contributor VARCHAR(64), userId BIGINT NOT NULL, resultJson JSON NOT NULL,
 createTime DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS course_asset (
 id BIGINT NOT NULL PRIMARY KEY, batchCode VARCHAR(128) NOT NULL, assetPath VARCHAR(512) NOT NULL, contentType VARCHAR(64) NOT NULL,
 contentHash VARCHAR(64) NOT NULL, contentBytes MEDIUMBLOB NOT NULL, createTime DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 UNIQUE KEY uk_batch_path(batchCode,assetPath)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS course_graph_sync (
 id BIGINT NOT NULL PRIMARY KEY, importRunCode VARCHAR(128) NOT NULL UNIQUE,
 status VARCHAR(24) NOT NULL DEFAULT 'PENDING', errorMessage VARCHAR(1000),
 createTime DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updateTime DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

